
import type { InventoryReservationOwner } from './InventoryReservationOwner.js';
import type { InventoryRoutingSource } from './InventoryRoutingSource.js';
import type { ReservationLine } from './ReservationLine.js';

/** A claim on stock. Quantity moves from held to committed to consumed, and can be released or reallocated. */ export type InventoryReservation = { /** How the reservation ended. mixed when more than one terminal outcome applied. */ "closed_reason"?: "consumed" | "released" | "expired" | "reallocated" | "mixed" | null | (string & {}) | null; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "idempotency_key": string; /** Present when the claim needs a merchant action before commerce can continue. */ "inventory_action_required"?: { "inventory_reservation_line_ids": Array<string>; "next_actions": Array<"replenish" | "reallocate" | "cancel" | (string & {})>; "reason": "inventory_shortage" | (string & {}); }; "inventory_reservation_id": string; "inventory_routing_source": InventoryRoutingSource; "lines": Array<ReservationLine>; "owner": InventoryReservationOwner; "replacement_inventory_reservation_id"?: string; "source_inventory_reservation_id"?: string; /** active while any held or committed quantity remains; closed once none does. */ "status": "active" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
